function inicializarStatusEMetas() {
  oo = ({ c: t, color = null }) =>
    t.partido
      ? html`<span class="pm" style=${"color:" + (color || kt(t))}
          >${Nt(t)} ${t.n}</span
        >`
      : html`<span class="pm f3">${t.n}</span>`;
  Lo = ({ status: t, pst: e, cands: n = [] }) => {
    let s,
      a = !0;
    return (
      t === "eleito"
        ? (s = pt(n[0]) ? "Eleita" : "Eleito")
        : t === "eleitos"
          ? (s = n.length && n.every(pt) ? "Eleitas" : "Eleitos")
          : t === "um-eleito"
            ? (s = "1ª vaga definida")
            : t === "segundo-turno"
              ? (s = "2º turno")
              : t === "apurado"
                ? (s = "Totalizado")
                : ((a = !1), (s = e > 0 ? `Apurando ${Pe(e)}%` : "Aguardando")),
      html`<span class=${"chip" + (a ? " done" : "")}><i></i>${s}</span>`
    );
  };
  Oa = (t, e = 1) => {
    const n = ue[e].format(Math.abs(t) * 100);
    return n + (/^1,0+$/.test(n) ? " ponto" : " pontos");
  };
  wi = (t) => (e) => {
    if (e >= 0.5) return "passou de 50%";
    const n = ue[t].format((0.5 - e) * 100);
    return /^0,0+$/.test(n)
      ? "a menos de " + (t > 1 ? "0,01" : "0,1") + " ponto"
      : (/^1,0+$/.test(n) ? "falta " : "faltam ") + Oa(0.5 - e, t);
  };
  Ci = ({
    left: t,
    right: e,
    h: n = 8,
    done: s = !1,
    d: a = us(t.share, e.share),
    colors = null,
    showThresholdHints = true,
  }) =>
    html`<div class=${"goal" + (s ? " done" : "")} style=${"--h:" + n + "px"}>
      ${s ? null : html`<div class="gl" aria-hidden="true"><span>50%</span></div>`}
      <div
        class="gb"
        role="img"
        aria-label=${`${yt(t)} ${_t(t.share)}%, ${yt(e)} ${_t(e.share)}%; a linha do meio marca 50% dos votos computados das candidaturas`}
      >
        <i
          class="l"
          style=${`width:${ie(t.share, 0, 1) * 100}%;background:${colors?.[0] || nt(t)}`}
        ></i
        ><i
          class="r"
          style=${`width:${ie(e.share, 0, 1) * 100}%;background:${colors?.[1] || nt(e)}`}
        ></i
        ><span class="fifty"></span>
      </div>
      ${
        s || !showThresholdHints
          ? null
          : html`<div class="gc tn">
              <span><${tn} n=${t.share} fmt=${wi(a)} /></span
              ><span><${tn} n=${e.share} fmt=${wi(a)} /></span>
            </div>`
      }
    </div>`;
}

function inicializarLinhasEDuelos() {
  ml = ({ a: t, b: e, h: n = 4, fifty: s = !1 }) => {
    const a = nt(t),
      r = nt(e);
    return s
      ? html`<div class="dualw">
          <${ml} a=${t} b=${e} h=${n} /><span class="fifty"></span>
        </div>`
      : html`<div class="dual" style=${"--h:" + n + "px"}>
          <i
            key="a"
            style=${`flex-grow:${Math.max(0.001, t.share)};background:${a}`}
          ></i
          ><i
            key="m"
            style=${`flex-grow:${Math.max(0.001, 1 - t.share - e.share)};background:rgba(250,250,249,.1)`}
          ></i
          ><i
            key="b"
            style=${`flex-grow:${Math.max(0.001, e.share)};background:${r}`}
          ></i>
        </div>`;
  };
  Ra = {
    open: null,
  };
  Po = (t) =>
    Ra.open && t && t.id != null
      ? {
          onClick: (e) => {
            (e.stopPropagation(), Ra.open(t));
          },
          onKeyDown: (e) => {
            (e.key === "Enter" || e.key === " ") &&
              (e.preventDefault(), e.stopPropagation(), Ra.open(t));
          },
          role: "button",
          tabIndex: 0,
          "aria-label": [
            "Ver detalhes de " + yt(t),
            t.partido ? Nt(t) + " " + t.n : t.n,
            Number.isFinite(t.share) ? _t(t.share, 2) + "%" : null,
            Number.isFinite(t.votes) ? ht(t.votes) + " votos" : null,
          ]
            .filter((value) => value != null)
            .join(" · "),
        }
      : {};
  Io = (t) => (Ra.open && t && t.id != null ? " clk" : "");
  os = ({ c: t, size: e = 32, bar: n = !1, votes: s = !1, cls: a = "" }) =>
    html`<div class=${"crow " + a + Io(t)} ...${Po(t)}>
      <${an} c=${t} size=${e} round />
      <div class="who">
        <div class="nm">${yt(t)}</div>
        <${oo} c=${t} />
      </div>
      <div class="val">
        <${tn}
          n=${t.share}
          fmt=${Ee}
        />${s ? html`<small><${tn} n=${t.votes} fmt=${ht} /></small>` : null}
      </div>
      ${
        n
          ? html`<div class="bar" style="--h:3px">
              <div class="clip">
                <i
                  key="v"
                  style=${`flex-grow:${t.share};background:${nt(t)}`}
                ></i
                ><i
                  key="r"
                  style=${`flex-grow:${1 - t.share};background:transparent`}
                ></i>
              </div>
            </div>`
          : null
      }
    </div>`;
  Mi = ({ a: t, b: e, size: n = 40, spot: s = null }) => {
    const a = [kt(t), kt(e)],
      r = us(t.share, e.share);
    return html`<div class="duel">
      ${[t, e].map(
        (u, i) =>
          html`<div
            class=${"cand" + (i ? " r" : "") + (u.id === s ? " spot" : "") + Io(u)}
            key=${u.id}
            ...${Po(u)}
          >
            <div class="who">
              <${an} c=${u} size=${n} />
              <div>
                <div class="nm">${yt(u)}</div>
                <${oo} c=${u} />
              </div>
            </div>
            <div class="fig" style=${"color:" + a[i]}>
              <${tn} n=${u.share} fmt=${(c) => _t(c, r)} /><sup>%</sup>
            </div>
          </div>`,
      )}
    </div>`;
  };
}

function inicializarMomentoDaApuracao() {
  vl = (t) => {
    if (t.empty) return "wait";
    if (t.n.status !== "apurando") return t.n.status;
    if (t.n.pst <= 0) return "start";
    if (t.n.pst < 0.01)
      return Sim.UFS.every((n) => t.ufs[n].pst <= 0) ? "abroad" : "early";
    const e = ma.filter((n) => n.t <= t.t).pop();
    return e && t.t - e.t < 20 && lt[e.to].id === t.pres[0].id
      ? "virada"
      : "lead:" + t.pres[0].id;
  };
  xu = () => {
    const [, t] = useState(0);
    useEffect(() => {
      let i;
      const c = () => {
        i = setTimeout(
          () => {
            (t((l) => l + 1), c());
          },
          1005 - (Date.now() % 1e3),
        );
      };
      return (c(), () => clearTimeout(i));
    }, []);
    const e = Feed.minuteOf(Date.now()),
      n = Math.ceil((Oe - e) * 60),
      s = (i) => String(i).padStart(2, "0");
    if (e < 0)
      return Oe - e > 1440
        ? `A apuração começa no dia ${Xt === 2 ? 25 : 4}, às 17:00`
        : "A apuração começa amanhã às 17:00";
    if (n <= 0) return "A apuração começou às 17:00";
    const a = Math.floor(n / 3600),
      r = Math.floor((n % 3600) / 60),
      u = n % 60;
    return html`<span class="ln">A apuração começa em</span
      ><span class="ln nb tn" role="timer"
        >${a ? `${a}:${s(r)}:${s(u)}` : `${r}:${s(u)}`}</span
      >`;
  };
}

export function initialize() {
  inicializarPresencaEAvatares();
  inicializarCoresEListas();
  inicializarMarcaERedes();
  inicializarStatusEMetas();
  inicializarLinhasEDuelos();
  inicializarMomentoDaApuracao();
}
